/// Device/resource snapshot of the advanced CStdGL raster switches.
///
/// The native renderer reads these values while restoring its device and
/// then applies the immutable snapshot to later draw submissions. The Rust
/// backend keeps the same ownership model even though its renderer is CPU
/// based and can install the snapshot without recreating an OS GL context.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct AdvancedRendererConfig {
    pub no_alpha_add: bool,
    pub no_box_fades: bool,
    pub tex_indent: i32,
    pub blit_offset: i32,
    pub allowed_blit_modes: u32,
    pub shader: bool,
    pub use_shader_gamma: bool,
    pub disable_gamma: bool,
}

impl AdvancedRendererConfig {
    pub const DEFAULT: Self = Self {
        no_alpha_add: false,
        no_box_fades: false,
        tex_indent: 0,
        blit_offset: 0,
        allowed_blit_modes: 15,
        shader: false,
        use_shader_gamma: true,
        disable_gamma: false,
    };

    fn masked_blit_mode(self, mode: u32) -> u32 {
        mode & self.allowed_blit_modes
    }

    fn texture_indent(self) -> f32 {
        self.tex_indent as f32 / 1000.0
    }

    fn destination_offset(self) -> f32 {
        self.blit_offset as f32 / 100.0
    }

    fn has_adjusted_quad_geometry(self) -> bool {
        self.tex_indent != 0 || self.blit_offset != 0
    }

    fn changes_generic_textured_blit(self, requested_mode: u32, modulated: bool) -> bool {
        self.has_adjusted_quad_geometry()
            || self.masked_blit_mode(requested_mode) != requested_mode
            || (modulated && !self.shader && self.no_alpha_add)
    }

    fn changes_generic_color_quad(self) -> bool {
        self.blit_offset != 0 || self.no_box_fades
    }

    fn uses_fragment_gamma(self) -> bool {
        !self.disable_gamma && self.shader && self.use_shader_gamma
    }

    fn uses_monitor_gamma(self) -> bool {
        !self.disable_gamma && !self.uses_fragment_gamma()
    }
}

impl Default for AdvancedRendererConfig {
    fn default() -> Self {
        Self::DEFAULT
    }
}

thread_local! {
    /// CStdDDraw owns one renderer/device on the presentation thread. Keep
    /// generic GUI helpers source-compatible while allowing a production
    /// frame to expose that immutable device snapshot to every nested draw.
    static ACTIVE_ADVANCED_RENDERER_CONFIG: Cell<Option<AdvancedRendererConfig>> =
        const { Cell::new(None) };
}

/// Restores the previous generic-draw renderer snapshot when a nested render
/// scope completes. The marker deliberately keeps the guard on the thread
/// whose TLS value it replaced.
#[must_use = "the renderer configuration remains active only while the guard is alive"]
pub struct AdvancedRendererConfigGuard {
    previous: Option<AdvancedRendererConfig>,
    _clonk_text_blit: lc_graphics::clonk_font::ClonkTextBlitConfigGuard,
    _not_send_or_sync: PhantomData<Rc<()>>,
}

impl Drop for AdvancedRendererConfigGuard {
    fn drop(&mut self) {
        ACTIVE_ADVANCED_RENDERER_CONFIG.with(|active| active.set(self.previous));
    }
}

/// Activates one immutable CStdGL device snapshot for generic GUI/HUD draw
/// submissions on the current presentation thread. Scopes are nest-safe and
/// callers outside a scope retain the historical compatibility path.
pub fn activate_advanced_renderer_config(
    config: AdvancedRendererConfig,
) -> AdvancedRendererConfigGuard {
    let clonk_text_blit = lc_graphics::clonk_font::activate_clonk_text_blit_config(
        lc_graphics::clonk_font::ClonkTextBlitConfig {
            no_alpha_add: config.no_alpha_add,
            tex_indent: config.tex_indent,
            blit_offset: config.blit_offset,
            allowed_blit_modes: config.allowed_blit_modes,
            shader: config.shader,
        },
    );
    let previous = ACTIVE_ADVANCED_RENDERER_CONFIG.with(|active| active.replace(Some(config)));
    AdvancedRendererConfigGuard {
        previous,
        _clonk_text_blit: clonk_text_blit,
        _not_send_or_sync: PhantomData,
    }
}

pub(crate) fn active_advanced_renderer_config() -> Option<AdvancedRendererConfig> {
    ACTIVE_ADVANCED_RENDERER_CONFIG.with(Cell::get)
}

/// C4GraphicsResource loads this 6-bit RGB palette and expands every channel
/// by `<< 2` (src/C4GraphicsResource.cpp:176-193). Typed line definitions
/// retain palette indices all the way to `C4FacetEx::DrawLine`.
const C4_GAME_PALETTE: &[u8; 256 * 3] = include_bytes!("../../../../planet/Graphics.c4g/C4.PAL");

/// The per-game palette installed by `C4GraphicsResource::Init`. Source
/// bytes use C4.PAL's six-bit RGB channels; indices 0 and 191 receive the
/// engine's fixed transparency/force-field overrides after expansion.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct GamePalette {
    colors: [Color; 256],
}

impl GamePalette {
    pub const BYTE_LEN: usize = 256 * 3;

    pub fn from_c4_pal(bytes: &[u8]) -> Option<Self> {
        if bytes.len() < Self::BYTE_LEN {
            return None;
        }
        let mut colors = [Color::opaque(0, 0, 0); 256];
        for (index, color) in colors.iter_mut().enumerate() {
            let offset = index * 3;
            *color = Color::opaque(
                bytes[offset] << 2,
                bytes[offset + 1] << 2,
                bytes[offset + 2] << 2,
            );
        }
        colors[0] = Color::transparent();
        colors[191] = Color::new(0, 0, 255, 128);
        Some(Self { colors })
    }

    pub fn color(&self, index: u8) -> Color {
        self.colors[usize::from(index)]
    }
}

impl Default for GamePalette {
    fn default() -> Self {
        Self::from_c4_pal(C4_GAME_PALETTE).expect("embedded C4.PAL has 256 RGB entries")
    }
}

/// One native material texture surface. PNG entries carry `Surface32`, while
/// legacy indexed BMP entries carry `Surface8`; C++ uses both for landscape
/// patterns but permits only `Surface32` as graphical PXS artwork.
#[derive(Clone, Debug, PartialEq)]
pub enum MaterialTextureSurface {
    Surface32(ImageData),
    Surface8 {
        width: u32,
        height: u32,
        indices: Arc<[u8]>,
    },
}

impl MaterialTextureSurface {
    pub fn surface32(image: ImageData) -> Self {
        Self::Surface32(image)
    }

    pub fn surface8(width: u32, height: u32, indices: Vec<u8>) -> Self {
        Self::Surface8 {
            width,
            height,
            indices: Arc::from(indices.into_boxed_slice()),
        }
    }

    pub fn surface32_image(&self) -> Option<&ImageData> {
        match self {
            Self::Surface32(image) => Some(image),
            Self::Surface8 { .. } => None,
        }
    }

    pub fn indexed_pixels(&self) -> Option<(u32, u32, &[u8])> {
        match self {
            Self::Surface32(_) => None,
            Self::Surface8 {
                width,
                height,
                indices,
            } => Some((*width, *height, indices)),
        }
    }
}

/// Presentation fields from one C4MaterialCore. Colors and alpha retain the
/// C++ arrays verbatim: three RGB triplets and two sets of three transparency
/// values (`0` opaque, `255` transparent).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MaterialRenderInfo {
    color: [u8; 9],
    alpha: [u8; 6],
    texture_overlay: Option<String>,
    overlay_type: i32,
    density: i32,
    /// C4MaterialCore::Placement after its load-time defaulting. ApplyLighting
    /// compares this value around each Surface8 pixel.
    placement: i32,
    /// Loose-material sprite sheet (`C4MaterialCore::sPXSGfx`). The sheet is
    /// resolved through the same texture map as landscape patterns.
    pxs_gfx: Option<String>,
    /// `C4TargetRect` [x, y, width, height, target-x, target-y].
    pxs_gfx_rect: [i32; 6],
    pxs_gfx_size: i32,
}

impl MaterialRenderInfo {
    pub fn new(
        color: [u8; 9],
        alpha: [u8; 6],
        texture_overlay: Option<String>,
        overlay_type: i32,
        density: i32,
    ) -> Self {
        let placement = if density >= 50 {
            70
        } else if density >= 25 {
            10
        } else {
            5
        };
        Self {
            color,
            alpha,
            texture_overlay,
            overlay_type,
            density,
            placement,
            pxs_gfx: None,
            pxs_gfx_rect: [0; 6],
            pxs_gfx_size: 0,
        }
    }

    pub fn with_placement(mut self, placement: i32) -> Self {
        self.placement = placement;
        self
    }

    pub fn with_pxs_graphics(
        mut self,
        texture: Option<String>,
        rect: [i32; 6],
        size: i32,
    ) -> Self {
        self.pxs_gfx = texture;
        self.pxs_gfx_rect = rect;
        self.pxs_gfx_size = size;
        self
    }
}

#[derive(Clone, Copy)]
struct MaterialPixel {
    red: u8,
    green: u8,
    blue: u8,
    transparency: u8,
}

fn lighten_material_channel(channel: u8) -> u8 {
    if channel & 0x80 != 0 {
        255
    } else {
        channel << 1
    }
}

fn apply_material_pattern(
    pixel: &mut MaterialPixel,
    pattern: &ImageData,
    x: i32,
    y: i32,
    zoom: i32,
    monochrome: bool,
) {
    let width = pattern.width();
    let height = pattern.height();
    if width == 0 || height == 0 {
        return;
    }
    let sample_x = if zoom == 0 { x } else { x / zoom };
    let sample_y = if zoom == 0 { y } else { y / zoom };
    let source = (((sample_y as u32 % height) * width + sample_x as u32 % width) * 4) as usize;
    let data = pattern.pixels();
    if source + 4 > data.len() {
        return;
    }

    let modifiers = if monochrome {
        [data[source + 2]; 3]
    } else {
        [data[source], data[source + 1], data[source + 2]]
    };
    pixel.red = lighten_material_channel(
        ((u16::from(pixel.red) * u16::from(modifiers[0])) >> 8) as u8,
    );
    pixel.green = lighten_material_channel(
        ((u16::from(pixel.green) * u16::from(modifiers[1])) >> 8) as u8,
    );
    pixel.blue = lighten_material_channel(
        ((u16::from(pixel.blue) * u16::from(modifiers[2])) >> 8) as u8,
    );
    let pattern_transparency = 255u8.saturating_sub(data[source + 3]);
    pixel.transparency = pixel
        .transparency
        .saturating_add(pattern_transparency);
}

#[derive(Clone, Copy)]
enum MaterialPatternRef<'a> {
    Surface32(&'a ImageData),
    Surface8 {
        width: u32,
        height: u32,
        indices: &'a [u8],
    },
}

impl<'a> From<&'a MaterialTextureSurface> for MaterialPatternRef<'a> {
    fn from(surface: &'a MaterialTextureSurface) -> Self {
        match surface {
            MaterialTextureSurface::Surface32(image) => Self::Surface32(image),
            MaterialTextureSurface::Surface8 {
                width,
                height,
                indices,
            } => Self::Surface8 {
                width: *width,
                height: *height,
                indices,
            },
        }
    }
}

fn apply_indexed_material_pattern(
    pixel: &mut MaterialPixel,
    material: &MaterialRenderInfo,
    landscape_pixel: u8,
    width: u32,
    height: u32,
    indices: &[u8],
    x: i32,
    y: i32,
    zoom: i32,
) {
    if width == 0 || height == 0 {
        return;
    }
    let sample_x = if zoom == 0 { x } else { x / zoom };
    let sample_y = if zoom == 0 { y } else { y / zoom };
    let source = (sample_y as u32 % height) as usize * width as usize
        + (sample_x as u32 % width) as usize;
    let Some(&shift) = indices.get(source) else {
        return;
    };
    let shift = usize::from(shift % 3);
    let color = shift * 3;
    pixel.red = material.color[color];
    pixel.green = material.color[color + 1];
    pixel.blue = material.color[color + 2];
    pixel.transparency = material.alpha[shift + if landscape_pixel & 0xf0 == 0 { 0 } else { 3 }];
}

fn apply_material_surface(
    pixel: &mut MaterialPixel,
    material: &MaterialRenderInfo,
    landscape_pixel: u8,
    pattern: MaterialPatternRef<'_>,
    x: i32,
    y: i32,
    zoom: i32,
    monochrome: bool,
) {
    match pattern {
        MaterialPatternRef::Surface32(pattern) => {
            apply_material_pattern(pixel, pattern, x, y, zoom, monochrome)
        }
        MaterialPatternRef::Surface8 {
            width,
            height,
            indices,
        } => apply_indexed_material_pattern(
            pixel,
            material,
            landscape_pixel,
            width,
            height,
            indices,
            x,
            y,
            zoom,
        ),
    }
}

#[cfg(test)]
std::thread_local! {
    static MATERIAL_COMPOSITION_CALLS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
    // Each test thread owns its counter while scoped Rayon workers receive an
    // Arc clone from that originating thread. This retains test isolation and
    // makes increments from parallel landscape rows race-free.
    static LANDSCAPE_DESTINATION_SAMPLES: Arc<AtomicUsize> = Arc::new(AtomicUsize::new(0));
}

#[cfg(test)]
fn reset_material_composition_calls() {
    MATERIAL_COMPOSITION_CALLS.with(|calls| calls.set(0));
}

#[cfg(test)]
fn material_composition_calls() -> usize {
    MATERIAL_COMPOSITION_CALLS.with(std::cell::Cell::get)
}

#[cfg(test)]
fn reset_landscape_destination_samples() {
    LANDSCAPE_DESTINATION_SAMPLES.with(|samples| samples.store(0, Ordering::Relaxed));
}

#[cfg(test)]
fn landscape_destination_samples() -> usize {
    LANDSCAPE_DESTINATION_SAMPLES.with(|samples| samples.load(Ordering::Relaxed))
}

fn compose_material_pixel(
    material: &MaterialRenderInfo,
    landscape_pixel: u8,
    x: i32,
    y: i32,
    texture: &ImageData,
    overlay: Option<&ImageData>,
) -> Color {
    compose_material_surface_pixel(
        material,
        landscape_pixel,
        x,
        y,
        MaterialPatternRef::Surface32(texture),
        overlay.map(MaterialPatternRef::Surface32),
    )
}

fn compose_material_surface_pixel(
    material: &MaterialRenderInfo,
    landscape_pixel: u8,
    x: i32,
    y: i32,
    texture: MaterialPatternRef<'_>,
    overlay: Option<MaterialPatternRef<'_>>,
) -> Color {
    #[cfg(test)]
    MATERIAL_COMPOSITION_CALLS.with(|calls| calls.set(calls.get() + 1));

    let mut pixel = MaterialPixel {
        red: material.color[0],
        green: material.color[1],
        blue: material.color[2],
        transparency: material.alpha[if landscape_pixel & 0x80 == 0 { 0 } else { 3 }],
    };
    let primary_zoom = if material.overlay_type & MATERIAL_OVERLAY_HUGE_ZOOM != 0 {
        4
    } else if material.overlay_type & MATERIAL_OVERLAY_EXACT != 0 {
        1
    } else {
        0
    };
    let monochrome = material.overlay_type & MATERIAL_OVERLAY_MONOCHROME != 0;
    apply_material_surface(
        &mut pixel,
        material,
        landscape_pixel,
        texture,
        x,
        y,
        primary_zoom,
        monochrome,
    );
    if let Some(overlay) = overlay {
        let overlay_zoom = if material.overlay_type & MATERIAL_OVERLAY_EXACT != 0 {
            1
        } else {
            2
        };
        apply_material_surface(
            &mut pixel,
            material,
            landscape_pixel,
            overlay,
            x,
            y,
            overlay_zoom,
            monochrome,
        );
    }
    Color::new(
        pixel.red,
        pixel.green,
        pixel.blue,
        255u8.saturating_sub(pixel.transparency),
    )
}

fn lighten_material_color(color: &mut Color, amount: i32) {
    let amount = amount.clamp(0, 255) as u8;
    color.r = color.r.saturating_add(amount);
    color.g = color.g.saturating_add(amount);
    color.b = color.b.saturating_add(amount);
}

fn darken_material_color(color: &mut Color, amount: i32) {
    let amount = amount.clamp(0, 255) as u8;
    color.r = color.r.saturating_sub(amount);
    color.g = color.g.saturating_sub(amount);
    color.b = color.b.saturating_sub(amount);
}

